    private AuditActionFilter createFilterWithResolveBulk(boolean resolveBulk) {
        Settings settings = Settings.builder().put(ConfigConstants.OPENDISTRO_SECURITY_AUDIT_RESOLVE_BULK_REQUESTS, resolveBulk).build();
